CREATE OR REPLACE FUNCTION public.validate_news_submission() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE k text; p text; wc integer; BEGIN IF TG_OP='INSERT' THEN wc:=array_length(regexp_split_to_array(trim(NEW.script),'\s+'),1); IF wc<80 OR wc>100 THEN RAISE EXCEPTION 'Script must contain 80 to 100 words'; END IF; IF length(trim(NEW.headline))<10 OR length(NEW.headline)>120 THEN RAISE EXCEPTION 'Invalid headline'; END IF; IF NEW.clip_paths <> '{}'::jsonb THEN FOREACH k IN ARRAY ARRAY['location','anchor','byte1','byte2'] LOOP p:=NEW.clip_paths->>k; IF p IS NULL OR p NOT LIKE NEW.reporter_id::text || '/%' THEN RAISE EXCEPTION 'Four owned video clips required for video news'; END IF; END LOOP; END IF; END IF; RETURN NEW; END $$;